-- Workspace schema baseline for the PostgreSQL team-server backend.
--
-- Final state of a fresh SQLite memory.db after migrations/001..037 and the
-- Store._schema/_migrate Python ALTERs, applied by tam_db.pg_schema.ensure()
-- inside the workspace schema (the first entry of search_path; extensions such
-- as vector live in schema "extensions", also on search_path). Later workspace
-- changes are 0002_*.sql and up; the SQLite migration history is recorded as
-- rows of the "migrations" table below, exactly as a fresh SQLite store has it.
--
-- Mapping rules (tests/test_pg_schema_parity.py checks them against a fresh
-- SQLite Store):
--   * column order is SQLite's, including columns ALTER TABLE appended, so
--     positional INSERTs keep working;
--   * INTEGER/BOOLEAN -> bigint, TEXT/JSON -> text, REAL -> double precision,
--     BLOB -> bytea; timestamps stay ISO-8601 text;
--   * INTEGER PRIMARY KEY (a rowid alias) -> bigint GENERATED BY DEFAULT AS
--     IDENTITY; ids are never reused;
--   * FOREIGN KEY clauses are not declared: the SQLite store runs with
--     PRAGMA foreign_keys=OFF, so neither the references nor their ON DELETE
--     actions are enforced there. The triggers below carry the integrity rules
--     the store relies on;
--   * the 25 SQLite triggers keep their names and behaviour in PL/pgSQL;
--     RAISE(ABORT, ...) becomes RAISE EXCEPTION (SQLSTATE P0001, surfaced as
--     sqlite3.IntegrityError by tam_db);
--   * the five FTS5 tables become side tables (<table>_tsv) holding the
--     unicode61-equivalent token arrays of each indexed column, maintained by
--     the same trigger names, with GIN indexes for matching and fts_stats for
--     BM25 (memory_core.pg_fts compiles MATCH expressions against them).

-- SQLite strftime('%Y-%m-%dT%H:%M:%SZ', 'now'): statement time in UTC, whole seconds.
CREATE FUNCTION tam_utc_now() RETURNS text
LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
$$;

-- SQLite strftime('%Y-%m-%dT%H:%M:%fZ', 'now'): the same with milliseconds.
CREATE FUNCTION tam_utc_now_ms() RETURNS text
LANGUAGE sql STABLE PARALLEL SAFE AS $$
    SELECT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
$$;

-- knowledge.fts_project: SQLite 'p' || lower(hex(project)); hex(NULL) is ''.
-- convert_to is STABLE only because of the encoding argument; the database
-- encoding is UTF8 by prerequisite, so the result depends on the input alone.
CREATE FUNCTION tam_fts_project_token(project text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    SELECT 'p' || COALESCE(encode(convert_to(project, 'UTF8'), 'hex'), '')
$$;

-- Tokens of `value` exactly as the FTS5 unicode61 tokenizer (remove_diacritics=1)
-- produces them: split on every character FTS5 treats as a separator, fold case,
-- then strip diacritics the way FTS5 does (a character-for-character map; the 25
-- combining marks FTS5 drops are deleted). Both tables were derived from SQLite's
-- own tokenizer over every Unicode code point; tests/test_pg_fts.py re-derives them
-- and fails when they drift. Folding runs per token and only on tokens holding a
-- mapped character, so text without diacritics costs one regexp split.
-- Tokens are cut to 500 characters (at most 2000 bytes) because a tsvector lexeme
-- holds at most 2046 bytes; FTS5 has no such limit.
CREATE FUNCTION tam_fts_tokens(value text) RETURNS text[]
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    SELECT COALESCE(array_agg(left(folded, 500) ORDER BY position), '{}')
    FROM (
        SELECT CASE WHEN token ~ '[\u00b5\u00e0-\u00e5\u00e7-\u00ef\u00f1-\u00f6\u00f9-\u00fd\u00ff\u0101\u0103\u0105\u0107\u0109\u010b\u010d\u010f\u0113\u0115\u0117\u0119\u011b\u011d\u011f\u0121\u0123\u0125\u0129\u012b\u012d\u012f\u0135\u0137\u013a\u013c\u013e\u0144\u0146\u0148\u014d\u014f\u0151\u0155\u0157\u0159\u015b\u015d\u015f\u0161\u0163\u0165\u0169\u016b\u016d\u016f\u0171\u0173\u0175\u0177\u017a\u017c\u017e-\u017f\u01a1\u01b0\u01ce\u01d0\u01d2\u01d4\u01e7\u01e9\u01eb\u01f0\u01f5\u01f9\u0201\u0203\u0205\u0207\u0209\u020b\u020d\u020f\u0211\u0213\u0215\u0217\u0219\u021b\u021f\u0227\u0229\u022f\u0233\u0300-\u0304\u0306-\u030c\u030f\u0311\u031b\u0323-\u0328\u032d-\u032e\u0330-\u0331\u03c2\u03d0-\u03d1\u03d5-\u03d6\u03f0-\u03f1\u03f5\u1e01\u1e03\u1e05\u1e07\u1e0b\u1e0d\u1e0f\u1e11\u1e13\u1e19\u1e1b\u1e1f\u1e21\u1e23\u1e25\u1e27\u1e29\u1e2b\u1e2d\u1e31\u1e33\u1e35\u1e37\u1e3b\u1e3d\u1e3f\u1e41\u1e43\u1e45\u1e47\u1e49\u1e4b\u1e55\u1e57\u1e59\u1e5b\u1e5f\u1e61\u1e63\u1e6b\u1e6d\u1e6f\u1e71\u1e73\u1e75\u1e77\u1e7d\u1e7f\u1e81\u1e83\u1e85\u1e87\u1e89\u1e8b\u1e8d\u1e8f\u1e91\u1e93\u1e95-\u1e99\u1e9b\u1ea1\u1ea3\u1eb9\u1ebb\u1ebd\u1ec9\u1ecb\u1ecd\u1ecf\u1ee5\u1ee7\u1ef3\u1ef5\u1ef7\u1ef9\u1fbe]'
                    THEN translate(token, U&'\00B5\00E0\00E1\00E2\00E3\00E4\00E5\00E7\00E8\00E9\00EA\00EB\00EC\00ED\00EE\00EF\00F1\00F2\00F3\00F4\00F5\00F6\00F9\00FA\00FB\00FC\00FD\00FF\0101\0103\0105\0107\0109\010B\010D\010F\0113\0115\0117\0119\011B\011D\011F\0121\0123\0125\0129\012B\012D\012F\0135\0137\013A\013C\013E\0144\0146\0148\014D\014F\0151\0155\0157\0159\015B\015D\015F\0161\0163\0165\0169\016B\016D\016F\0171\0173\0175\0177\017A\017C\017E\017F\01A1\01B0\01CE\01D0\01D2\01D4\01E7\01E9\01EB\01F0\01F5\01F9\0201\0203\0205\0207\0209\020B\020D\020F\0211\0213\0215\0217\0219\021B\021F\0227\0229\022F\0233\03C2\03D0\03D1\03D5\03D6\03F0\03F1\03F5\1E01\1E03\1E05\1E07\1E0B\1E0D\1E0F\1E11\1E13\1E19\1E1B\1E1F\1E21\1E23\1E25\1E27\1E29\1E2B\1E2D\1E31\1E33\1E35\1E37\1E3B\1E3D\1E3F\1E41\1E43\1E45\1E47\1E49\1E4B\1E55\1E57\1E59\1E5B\1E5F\1E61\1E63\1E6B\1E6D\1E6F\1E71\1E73\1E75\1E77\1E7D\1E7F\1E81\1E83\1E85\1E87\1E89\1E8B\1E8D\1E8F\1E91\1E93\1E95\1E96\1E97\1E98\1E99\1E9B\1EA1\1EA3\1EB9\1EBB\1EBD\1EC9\1ECB\1ECD\1ECF\1EE5\1EE7\1EF3\1EF5\1EF7\1EF9\1FBE\0300\0301\0302\0303\0304\0306\0307\0308\0309\030A\030B\030C\030F\0311\031B\0323\0324\0325\0326\0327\0328\032D\032E\0330\0331', U&'\03BC\0061\0061\0061\0061\0061\0061\0063\0065\0065\0065\0065\0069\0069\0069\0069\006E\006F\006F\006F\006F\006F\0075\0075\0075\0075\0079\0079\0061\0061\0061\0063\0063\0063\0063\0064\0065\0065\0065\0065\0065\0067\0067\0067\0067\0068\0069\0069\0069\0069\006A\006B\006C\006C\006C\006E\006E\006E\006F\006F\006F\0072\0072\0072\0073\0073\0073\0073\0074\0074\0075\0075\0075\0075\0075\0075\0077\0079\007A\007A\007A\0073\006F\0075\0061\0069\006F\0075\0067\006B\006F\006A\0067\006E\0061\0061\0065\0065\0069\0069\006F\006F\0072\0072\0075\0075\0073\0074\0068\0061\0065\006F\0079\03C3\03B2\03B8\03C6\03C0\03BA\03C1\03B5\0061\0062\0062\0062\0064\0064\0064\0064\0064\0065\0065\0066\0067\0068\0068\0068\0068\0068\0069\006B\006B\006B\006C\006C\006C\006D\006D\006D\006E\006E\006E\006E\0070\0070\0072\0072\0072\0073\0073\0074\0074\0074\0074\0075\0075\0075\0076\0076\0077\0077\0077\0077\0077\0078\0078\0079\007A\007A\007A\0068\0074\0077\0079\0073\0061\0061\0065\0065\0065\0069\0069\006F\006F\0075\0075\0079\0079\0079\0079\03B9')
                    ELSE token END AS folded,
               position
        FROM regexp_split_to_table(lower(value), '[\u0001-\u002f\u003a-\u0040\u005b-\u0060\u007b-\u00a9\u00ab-\u00b1\u00b4\u00b6-\u00b8\u00bb\u00bf\u00d7\u00f7\u02c2-\u02c5\u02d2-\u02df\u02e5-\u02eb\u02ed\u02ef-\u02ff\u0305\u030d-\u030e\u0310\u0312-\u031a\u031c-\u0322\u0329-\u032c\u032f\u0332-\u036f\u0375\u037e\u0384-\u0385\u0387\u03f6\u0482-\u0489\u055a-\u055f\u0589-\u058a\u058f\u0591-\u05c7\u05f3-\u05f4\u0600-\u0604\u0606-\u061b\u061e-\u061f\u064b-\u065f\u066a-\u066d\u0670\u06d4\u06d6-\u06e4\u06e7-\u06ed\u06fd-\u06fe\u0700-\u070d\u070f\u0711\u0730-\u074a\u07a6-\u07b0\u07eb-\u07f3\u07f6-\u07f9\u0816-\u0819\u081b-\u0823\u0825-\u0827\u0829-\u082d\u0830-\u083e\u0859-\u085b\u085e\u08e4-\u08fe\u0900-\u0903\u093a-\u093c\u093e-\u094f\u0951-\u0957\u0962-\u0965\u0970\u0981-\u0983\u09bc\u09be-\u09c4\u09c7-\u09c8\u09cb-\u09cd\u09d7\u09e2-\u09e3\u09f2-\u09f3\u09fa-\u09fb\u0a01-\u0a03\u0a3c\u0a3e-\u0a42\u0a47-\u0a48\u0a4b-\u0a4d\u0a51\u0a70-\u0a71\u0a75\u0a81-\u0a83\u0abc\u0abe-\u0ac5\u0ac7-\u0ac9\u0acb-\u0acd\u0ae2-\u0ae3\u0af0-\u0af1\u0b01-\u0b03\u0b3c\u0b3e-\u0b44\u0b47-\u0b48\u0b4b-\u0b4d\u0b56-\u0b57\u0b62-\u0b63\u0b70\u0b82\u0bbe-\u0bc2\u0bc6-\u0bc8\u0bca-\u0bcd\u0bd7\u0bf3-\u0bfa\u0c01-\u0c03\u0c3e-\u0c44\u0c46-\u0c48\u0c4a-\u0c4d\u0c55-\u0c56\u0c62-\u0c63\u0c7f\u0c82-\u0c83\u0cbc\u0cbe-\u0cc4\u0cc6-\u0cc8\u0cca-\u0ccd\u0cd5-\u0cd6\u0ce2-\u0ce3\u0d02-\u0d03\u0d3e-\u0d44\u0d46-\u0d48\u0d4a-\u0d4d\u0d57\u0d62-\u0d63\u0d79\u0d82-\u0d83\u0dca\u0dcf-\u0dd4\u0dd6\u0dd8-\u0ddf\u0df2-\u0df4\u0e31\u0e34-\u0e3a\u0e3f\u0e47-\u0e4f\u0e5a-\u0e5b\u0eb1\u0eb4-\u0eb9\u0ebb-\u0ebc\u0ec8-\u0ecd\u0f01-\u0f1f\u0f34-\u0f3f\u0f71-\u0f87\u0f8d-\u0f97\u0f99-\u0fbc\u0fbe-\u0fcc\u0fce-\u0fda\u102b-\u103e\u104a-\u104f\u1056-\u1059\u105e-\u1060\u1062-\u1064\u1067-\u106d\u1071-\u1074\u1082-\u108d\u108f\u109a-\u109f\u10fb\u135d-\u1368\u1390-\u1399\u1400\u166d-\u166e\u1680\u169b-\u169c\u16eb-\u16ed\u1712-\u1714\u1732-\u1736\u1752-\u1753\u1772-\u1773\u17b4-\u17d6\u17d8-\u17db\u17dd\u1800-\u180e\u18a9\u1920-\u192b\u1930-\u193b\u1940\u1944-\u1945\u19b0-\u19c0\u19c8-\u19c9\u19de-\u19ff\u1a17-\u1a1b\u1a1e-\u1a1f\u1a55-\u1a5e\u1a60-\u1a7c\u1a7f\u1aa0-\u1aa6\u1aa8-\u1aad\u1b00-\u1b04\u1b34-\u1b44\u1b5a-\u1b7c\u1b80-\u1b82\u1ba1-\u1bad\u1be6-\u1bf3\u1bfc-\u1bff\u1c24-\u1c37\u1c3b-\u1c3f\u1c7e-\u1c7f\u1cc0-\u1cc7\u1cd0-\u1ce8\u1ced\u1cf2-\u1cf4\u1dc0-\u1de6\u1dfc-\u1dff\u1fbd\u1fbf-\u1fc1\u1fcd-\u1fcf\u1fdd-\u1fdf\u1fed-\u1fef\u1ffd-\u1ffe\u2000-\u2064\u206a-\u206f\u207a-\u207e\u208a-\u208e\u20a0-\u20b9\u20d0-\u20f0\u2100-\u2101\u2103-\u2106\u2108-\u2109\u2114\u2116-\u2118\u211e-\u2123\u2125\u2127\u2129\u212e\u213a-\u213b\u2140-\u2144\u214a-\u214d\u214f\u2190-\u23f3\u2400-\u2426\u2440-\u244a\u249c-\u24e9\u2500-\u26ff\u2701-\u2775\u2794-\u2b4c\u2b50-\u2b59\u2ce5-\u2cea\u2cef-\u2cf1\u2cf9-\u2cfc\u2cfe-\u2cff\u2d70\u2d7f\u2de0-\u2e2e\u2e30-\u2e3b\u2e80-\u2e99\u2e9b-\u2ef3\u2f00-\u2fd5\u2ff0-\u2ffb\u3000-\u3004\u3008-\u3020\u302a-\u3030\u3036-\u3037\u303d-\u303f\u3099-\u309c\u30a0\u30fb\u3190-\u3191\u3196-\u319f\u31c0-\u31e3\u3200-\u321e\u322a-\u3247\u3250\u3260-\u327f\u328a-\u32b0\u32c0-\u32fe\u3300-\u33ff\u4dc0-\u4dff\ua490-\ua4c6\ua4fe-\ua4ff\ua60d-\ua60f\ua66f-\ua67e\ua69f\ua6f0-\ua6f7\ua700-\ua716\ua720-\ua721\ua789-\ua78a\ua802\ua806\ua80b\ua823-\ua82b\ua836-\ua839\ua874-\ua877\ua880-\ua881\ua8b4-\ua8c4\ua8ce-\ua8cf\ua8e0-\ua8f1\ua8f8-\ua8fa\ua926-\ua92f\ua947-\ua953\ua95f\ua980-\ua983\ua9b3-\ua9cd\ua9de-\ua9df\uaa29-\uaa36\uaa43\uaa4c-\uaa4d\uaa5c-\uaa5f\uaa77-\uaa79\uaa7b\uaab0\uaab2-\uaab4\uaab7-\uaab8\uaabe-\uaabf\uaac1\uaade-\uaadf\uaaeb-\uaaf1\uaaf5-\uaaf6\uabe3-\uabed\ufb1e\ufb29\ufbb2-\ufbc1\ufd3e-\ufd3f\ufdfc-\ufdfd\ufe00-\ufe19\ufe20-\ufe26\ufe30-\ufe52\ufe54-\ufe66\ufe68-\ufe6b\ufeff\uff01-\uff0f\uff1a-\uff20\uff3b-\uff40\uff5b-\uff65\uffe0-\uffe6\uffe8-\uffee\ufff9-\uffff\U00010100-\U00010102\U00010137-\U0001013f\U00010179-\U00010189\U00010190-\U0001019b\U000101d0-\U000101fd\U0001039f\U000103d0\U00010857\U0001091f\U0001093f\U00010a01-\U00010a03\U00010a05-\U00010a06\U00010a0c-\U00010a0f\U00010a38-\U00010a3a\U00010a3f\U00010a50-\U00010a58\U00010a7f\U00010b39-\U00010b3f\U00011000-\U00011002\U00011038-\U0001104d\U00011080-\U00011082\U000110b0-\U000110c1\U00011100-\U00011102\U00011127-\U00011134\U00011140-\U00011143\U00011180-\U00011182\U000111b3-\U000111c0\U000111c5-\U000111c8\U000116ab-\U000116b7\U00012470-\U00012473\U00016f51-\U00016f7e\U00016f8f-\U00016f92\U0001d000-\U0001d0f5\U0001d100-\U0001d126\U0001d129-\U0001d1dd\U0001d200-\U0001d245\U0001d300-\U0001d356\U0001d6c1\U0001d6db\U0001d6fb\U0001d715\U0001d735\U0001d74f\U0001d76f\U0001d789\U0001d7a9\U0001d7c3\U0001eef0-\U0001eef1\U0001f000-\U0001f02b\U0001f030-\U0001f093\U0001f0a0-\U0001f0ae\U0001f0b1-\U0001f0be\U0001f0c1-\U0001f0cf\U0001f0d1-\U0001f0df\U0001f110-\U0001f12e\U0001f130-\U0001f16b\U0001f170-\U0001f19a\U0001f1e6-\U0001f202\U0001f210-\U0001f23a\U0001f240-\U0001f248\U0001f250-\U0001f251\U0001f300-\U0001f320\U0001f330-\U0001f335\U0001f337-\U0001f37c\U0001f380-\U0001f393\U0001f3a0-\U0001f3c4\U0001f3c6-\U0001f3ca\U0001f3e0-\U0001f3f0\U0001f400-\U0001f43e\U0001f440\U0001f442-\U0001f4f7\U0001f4f9-\U0001f4fc\U0001f500-\U0001f53d\U0001f540-\U0001f543\U0001f550-\U0001f567\U0001f5fb-\U0001f640\U0001f645-\U0001f64f\U0001f680-\U0001f6c5\U0001f700-\U0001f773\U000e0001\U000e0020-\U000e007f\U000e0100-\U000e01ef]+') WITH ORDINALITY AS t(token, position)
    ) AS tokens
    WHERE folded <> ''
$$;

-- token -> number of occurrences in `tokens`, for single-term frequencies.
CREATE FUNCTION tam_fts_counts(tokens text[]) RETURNS jsonb
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    SELECT COALESCE(jsonb_object_agg(token, occurrences), '{}')
    FROM (SELECT token, count(*) AS occurrences FROM unnest(tokens) AS token GROUP BY token) AS counted
$$;

-- Occurrences of `phrase` (consecutive tokens; with `prefix` its last token only
-- has to start the document token) in the token array `document`: FTS5's
-- per-column phrase frequency.
CREATE FUNCTION tam_fts_tf(document text[], phrase text[], prefix boolean) RETURNS integer
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
DECLARE
    phrase_length integer := cardinality(phrase);
    starts integer[];
    step integer;
BEGIN
    IF document IS NULL OR phrase IS NULL OR phrase_length = 0 THEN
        RETURN 0;
    END IF;
    IF phrase_length = 1 AND prefix THEN
        RETURN (SELECT count(*) FROM unnest(document) AS token WHERE starts_with(token, phrase[1]));
    END IF;
    starts := array_positions(document, phrase[1]);
    FOR step IN 2 .. phrase_length LOOP
        EXIT WHEN cardinality(starts) = 0;
        IF prefix AND step = phrase_length THEN
            starts := ARRAY(SELECT start FROM unnest(starts) AS start
                            WHERE starts_with(document[start + step - 1], phrase[step]));
        ELSE
            starts := ARRAY(SELECT start FROM unnest(starts) AS start
                            WHERE document[start + step - 1] = phrase[step]);
        END IF;
    END LOOP;
    RETURN cardinality(starts);
END
$$;

-- ─── Tables and indexes ────────────────────────────────────────────────────
-- Every btree key on a nullable column or expression is declared with SQLite's NULL
-- placement for its direction (ascending NULLS FIRST, descending NULLS LAST);
-- tam_db's translator appends the same clause to such ORDER BY terms, so an index
-- scan in either direction yields SQLite's order. Keys on NOT NULL columns keep the
-- default: the translator adds no clause for them, and a NULLS clause would stop
-- the index (and the primary key's) from serving the reverse direction.

CREATE TABLE sessions (
    id text PRIMARY KEY,
    started_at text NOT NULL,
    ended_at text,
    project text DEFAULT 'general',
    status text DEFAULT 'open',
    summary text,
    log_count bigint DEFAULT 0,
    branch text DEFAULT ''
);
CREATE INDEX idx_s_started ON sessions(started_at);

CREATE TABLE knowledge (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    session_id text NOT NULL,
    type text NOT NULL,
    content text NOT NULL,
    context text DEFAULT '',
    project text DEFAULT 'general',
    tags text DEFAULT '[]',
    status text DEFAULT 'active',
    superseded_by bigint,
    confidence double precision DEFAULT 1.0,
    source text DEFAULT 'explicit',
    created_at text NOT NULL,
    last_confirmed text,
    recall_count bigint DEFAULT 0,
    last_recalled text,
    branch text DEFAULT '',
    importance text NOT NULL DEFAULT 'medium',
    agent_id text DEFAULT NULL,
    parent_agent_id text DEFAULT NULL,
    source_format text NOT NULL DEFAULT 'auto',
    fts_project text GENERATED ALWAYS AS (tam_fts_project_token(project)) STORED,
    CHECK (source_format IN ('auto','conversation'))
);
CREATE INDEX idx_k_status ON knowledge(status NULLS FIRST);
CREATE INDEX idx_k_type ON knowledge(type);
CREATE INDEX idx_k_project ON knowledge(project NULLS FIRST);
CREATE INDEX idx_k_session ON knowledge(session_id);
CREATE INDEX idx_k_last_confirmed ON knowledge(last_confirmed NULLS FIRST);
CREATE INDEX idx_knowledge_importance ON knowledge(importance);
CREATE INDEX idx_knowledge_status_quality ON knowledge(status NULLS FIRST) WHERE status = 'quality_dropped';
CREATE INDEX idx_k_agent_id ON knowledge(agent_id NULLS FIRST) WHERE agent_id IS NOT NULL;
CREATE INDEX idx_k_parent_agent_id ON knowledge(parent_agent_id NULLS FIRST) WHERE parent_agent_id IS NOT NULL;
CREATE INDEX idx_knowledge_neighbors ON knowledge(project NULLS FIRST, session_id, status NULLS FIRST, created_at, id);

CREATE TABLE relations (
    from_id bigint,
    to_id bigint,
    type text,
    created_at text
);
