CREATE INDEX idx_vector_changes_revision ON vector_changes(revision);

-- ─── Full-text side tables (FTS5 equivalents) ──────────────────────────────
-- One row per indexed source row, id = the FTS5 rowid. Each indexed column is kept
-- three ways: the token array tam_fts_tokens() produces (positions, for phrase and
-- prefix frequencies), its lexemes as a stored tsvector with a GIN index (term and
-- prefix matching), and a token -> occurrences jsonb (single-term frequencies by a
-- binary search instead of an array scan per matched row). doc_length is the row's
-- token count over all FTS5 columns, the document length FTS5's bm25() uses.

CREATE TABLE fts_stats (
    source text PRIMARY KEY,
    doc_count bigint NOT NULL DEFAULT 0,
    total_length bigint NOT NULL DEFAULT 0
);

CREATE TABLE knowledge_tsv (
    id bigint PRIMARY KEY,
    content text[] NOT NULL,
    content_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(content)) STORED,
    content_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(content)) STORED,
    context text[] NOT NULL,
    context_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(context)) STORED,
    context_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(context)) STORED,
    tags text[] NOT NULL,
    tags_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(tags)) STORED,
    tags_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(tags)) STORED,
    fts_project text NOT NULL,
    doc_length integer NOT NULL
);
CREATE INDEX knowledge_tsv_content ON knowledge_tsv USING gin (content_lexemes);
CREATE INDEX knowledge_tsv_context ON knowledge_tsv USING gin (context_lexemes);
CREATE INDEX knowledge_tsv_tags ON knowledge_tsv USING gin (tags_lexemes);
CREATE INDEX knowledge_tsv_fts_project ON knowledge_tsv (fts_project);

CREATE TABLE errors_tsv (
    id bigint PRIMARY KEY,
    description text[] NOT NULL,
    description_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(description)) STORED,
    description_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(description)) STORED,
    context text[] NOT NULL,
    context_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(context)) STORED,
    context_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(context)) STORED,
    fix text[] NOT NULL,
    fix_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(fix)) STORED,
    fix_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(fix)) STORED,
    tags text[] NOT NULL,
    tags_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(tags)) STORED,
    tags_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(tags)) STORED,
    doc_length integer NOT NULL
);
CREATE INDEX errors_tsv_description ON errors_tsv USING gin (description_lexemes);
CREATE INDEX errors_tsv_context ON errors_tsv USING gin (context_lexemes);
CREATE INDEX errors_tsv_fix ON errors_tsv USING gin (fix_lexemes);
CREATE INDEX errors_tsv_tags ON errors_tsv USING gin (tags_lexemes);

CREATE TABLE atomic_facts_tsv (
    id bigint PRIMARY KEY,
    content text[] NOT NULL,
    content_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(content)) STORED,
    content_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(content)) STORED,
    doc_length integer NOT NULL
);
CREATE INDEX atomic_facts_tsv_content ON atomic_facts_tsv USING gin (content_lexemes);

CREATE TABLE evidence_passages_tsv (
    id bigint PRIMARY KEY,
    content text[] NOT NULL,
    content_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(content)) STORED,
    content_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(content)) STORED,
    doc_length integer NOT NULL
);
CREATE INDEX evidence_passages_tsv_content ON evidence_passages_tsv USING gin (content_lexemes);

CREATE TABLE episodes_v11_tsv (
    id bigint PRIMARY KEY,
    summary text[] NOT NULL,
    summary_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(summary)) STORED,
    summary_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(summary)) STORED,
    participants text[] NOT NULL,
    participants_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(participants)) STORED,
    participants_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(participants)) STORED,
    outcome text[] NOT NULL,
    outcome_lexemes tsvector GENERATED ALWAYS AS (array_to_tsvector(outcome)) STORED,
    outcome_counts jsonb GENERATED ALWAYS AS (tam_fts_counts(outcome)) STORED,
    doc_length integer NOT NULL
);
CREATE INDEX episodes_v11_tsv_summary ON episodes_v11_tsv USING gin (summary_lexemes);
CREATE INDEX episodes_v11_tsv_participants ON episodes_v11_tsv USING gin (participants_lexemes);
CREATE INDEX episodes_v11_tsv_outcome ON episodes_v11_tsv USING gin (outcome_lexemes);

INSERT INTO fts_stats (source) VALUES
    ('knowledge_tsv'), ('errors_tsv'), ('atomic_facts_tsv'), ('evidence_passages_tsv'), ('episodes_v11_tsv');

CREATE FUNCTION tam_fts_stats_add(stats_source text, documents integer, tokens bigint) RETURNS void
LANGUAGE sql AS $$
    UPDATE fts_stats SET doc_count = doc_count + documents, total_length = total_length + tokens
    WHERE source = stats_source
$$;

-- knowledge_fts: content, context, tags, fts_project (k_fts_i / k_fts_u / k_fts_d).
CREATE FUNCTION tam_knowledge_fts_sync() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    removed integer;
    added integer;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        DELETE FROM knowledge_tsv WHERE id = OLD.id RETURNING doc_length INTO removed;
        IF FOUND THEN
            PERFORM tam_fts_stats_add('knowledge_tsv', -1, -removed);
        END IF;
    END IF;
    IF TG_OP <> 'DELETE' THEN
        INSERT INTO knowledge_tsv (id, content, context, tags, fts_project, doc_length)
        SELECT NEW.id, content, context, tags, project[1],
               cardinality(content) + cardinality(context) + cardinality(tags) + cardinality(project)
        FROM (SELECT tam_fts_tokens(NEW.content) AS content, tam_fts_tokens(NEW.context) AS context,
                     tam_fts_tokens(NEW.tags) AS tags, tam_fts_tokens(NEW.fts_project) AS project) AS tokens
        RETURNING doc_length INTO added;
        PERFORM tam_fts_stats_add('knowledge_tsv', 1, added);
    END IF;
    RETURN NULL;
END
$$;

-- errors_fts: description, context, fix, tags (e_fts_i / e_fts_u / e_fts_d).
CREATE FUNCTION tam_errors_fts_sync() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    removed integer;
    added integer;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        DELETE FROM errors_tsv WHERE id = OLD.id RETURNING doc_length INTO removed;
        IF FOUND THEN
            PERFORM tam_fts_stats_add('errors_tsv', -1, -removed);
        END IF;
    END IF;
    IF TG_OP <> 'DELETE' THEN
        INSERT INTO errors_tsv (id, description, context, fix, tags, doc_length)
        SELECT NEW.id, description, context, fix, tags,
               cardinality(description) + cardinality(context) + cardinality(fix) + cardinality(tags)
        FROM (SELECT tam_fts_tokens(NEW.description) AS description, tam_fts_tokens(NEW.context) AS context,
                     tam_fts_tokens(NEW.fix) AS fix, tam_fts_tokens(NEW.tags) AS tags) AS tokens
        RETURNING doc_length INTO added;
        PERFORM tam_fts_stats_add('errors_tsv', 1, added);
    END IF;
    RETURN NULL;
END
$$;

-- atomic_facts_fts: content. atomic_fact_delete also drops the fact's sources,
-- as the SQLite trigger of the same name does.
CREATE FUNCTION tam_atomic_facts_fts_sync() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    removed integer;
    added integer;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        DELETE FROM atomic_facts_tsv WHERE id = OLD.id RETURNING doc_length INTO removed;
        IF FOUND THEN
            PERFORM tam_fts_stats_add('atomic_facts_tsv', -1, -removed);
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN
        DELETE FROM atomic_fact_sources WHERE fact_id = OLD.id;
        RETURN NULL;
    END IF;
    INSERT INTO atomic_facts_tsv (id, content, doc_length)
    SELECT NEW.id, content, cardinality(content) FROM (SELECT tam_fts_tokens(NEW.content) AS content) AS tokens
    RETURNING doc_length INTO added;
    PERFORM tam_fts_stats_add('atomic_facts_tsv', 1, added);
    RETURN NULL;
END
$$;

-- evidence_passages_fts: content (evidence_passages_insert / _update / _delete).
CREATE FUNCTION tam_evidence_passages_fts_sync() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    removed integer;
    added integer;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        DELETE FROM evidence_passages_tsv WHERE id = OLD.id RETURNING doc_length INTO removed;
        IF FOUND THEN
            PERFORM tam_fts_stats_add('evidence_passages_tsv', -1, -removed);
        END IF;
    END IF;
    IF TG_OP <> 'DELETE' THEN
        INSERT INTO evidence_passages_tsv (id, content, doc_length)
        SELECT NEW.id, content, cardinality(content) FROM (SELECT tam_fts_tokens(NEW.content) AS content) AS tokens
        RETURNING doc_length INTO added;
        PERFORM tam_fts_stats_add('evidence_passages_tsv', 1, added);
    END IF;
    RETURN NULL;
END
$$;

-- episodes_v11_fts: summary, participants, outcome. On SQLite the episode
-- extractor writes the contentless FTS row itself, indexing the participants as
-- the space-joined list and a missing outcome as ''; the column holds the JSON
-- array, so its elements are indexed here.
CREATE FUNCTION tam_fts_participants(participants text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    SELECT CASE WHEN participants IS JSON ARRAY
                THEN (SELECT string_agg(element, ' ' ORDER BY position)
                      FROM json_array_elements_text(participants::json) WITH ORDINALITY AS e(element, position))
                ELSE participants END
$$;

CREATE FUNCTION tam_episodes_v11_fts_sync() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    removed integer;
    added integer;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        DELETE FROM episodes_v11_tsv WHERE id = OLD.id RETURNING doc_length INTO removed;
        IF FOUND THEN
            PERFORM tam_fts_stats_add('episodes_v11_tsv', -1, -removed);
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN NULL;
    END IF;
    INSERT INTO episodes_v11_tsv (id, summary, participants, outcome, doc_length)
    SELECT NEW.id, summary, participants, outcome,
           cardinality(summary) + cardinality(participants) + cardinality(outcome)
    FROM (SELECT tam_fts_tokens(NEW.summary) AS summary,
                 tam_fts_tokens(tam_fts_participants(NEW.participants)) AS participants,
                 tam_fts_tokens(COALESCE(NEW.outcome, '')) AS outcome) AS tokens
    RETURNING doc_length INTO added;
    PERFORM tam_fts_stats_add('episodes_v11_tsv', 1, added);
    RETURN NULL;
END
$$;

CREATE TRIGGER k_fts_i AFTER INSERT ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_knowledge_fts_sync();
CREATE TRIGGER k_fts_u AFTER UPDATE OF content, context, tags, project ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_knowledge_fts_sync();
CREATE TRIGGER k_fts_d AFTER DELETE ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_knowledge_fts_sync();

CREATE TRIGGER e_fts_i AFTER INSERT ON errors
    FOR EACH ROW EXECUTE FUNCTION tam_errors_fts_sync();
CREATE TRIGGER e_fts_u AFTER UPDATE ON errors
    FOR EACH ROW EXECUTE FUNCTION tam_errors_fts_sync();
CREATE TRIGGER e_fts_d AFTER DELETE ON errors
    FOR EACH ROW EXECUTE FUNCTION tam_errors_fts_sync();

CREATE TRIGGER atomic_fact_insert AFTER INSERT ON atomic_facts
    FOR EACH ROW EXECUTE FUNCTION tam_atomic_facts_fts_sync();
CREATE TRIGGER atomic_fact_update AFTER UPDATE OF content ON atomic_facts
    FOR EACH ROW EXECUTE FUNCTION tam_atomic_facts_fts_sync();
CREATE TRIGGER atomic_fact_delete AFTER DELETE ON atomic_facts
    FOR EACH ROW EXECUTE FUNCTION tam_atomic_facts_fts_sync();

CREATE TRIGGER evidence_passages_insert AFTER INSERT ON evidence_passages
    FOR EACH ROW EXECUTE FUNCTION tam_evidence_passages_fts_sync();
CREATE TRIGGER evidence_passages_update AFTER UPDATE ON evidence_passages
    FOR EACH ROW EXECUTE FUNCTION tam_evidence_passages_fts_sync();
CREATE TRIGGER evidence_passages_delete AFTER DELETE ON evidence_passages
    FOR EACH ROW EXECUTE FUNCTION tam_evidence_passages_fts_sync();

CREATE TRIGGER episodes_v11_fts_insert AFTER INSERT ON episodes_v11
    FOR EACH ROW EXECUTE FUNCTION tam_episodes_v11_fts_sync();
CREATE TRIGGER episodes_v11_fts_update AFTER UPDATE OF summary, participants, outcome ON episodes_v11
    FOR EACH ROW EXECUTE FUNCTION tam_episodes_v11_fts_sync();
CREATE TRIGGER episodes_v11_fts_delete AFTER DELETE ON episodes_v11
    FOR EACH ROW EXECUTE FUNCTION tam_episodes_v11_fts_sync();

-- FTS5 'rebuild': re-derive every side table and fts_stats from the indexed tables
-- (repair, or after rows were loaded with triggers bypassed). Runs in the caller's
-- transaction; memory_core.pg_fts.rebuild() calls it.
CREATE FUNCTION tam_fts_rebuild() RETURNS void
LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM knowledge_tsv;
    INSERT INTO knowledge_tsv (id, content, context, tags, fts_project, doc_length)
    SELECT id, content, context, tags, project[1],
           cardinality(content) + cardinality(context) + cardinality(tags) + cardinality(project)
    FROM (SELECT id, tam_fts_tokens(content) AS content, tam_fts_tokens(context) AS context,
                 tam_fts_tokens(tags) AS tags, tam_fts_tokens(fts_project) AS project FROM knowledge) AS tokens;

    DELETE FROM errors_tsv;
    INSERT INTO errors_tsv (id, description, context, fix, tags, doc_length)
    SELECT id, description, context, fix, tags,
           cardinality(description) + cardinality(context) + cardinality(fix) + cardinality(tags)
    FROM (SELECT id, tam_fts_tokens(description) AS description, tam_fts_tokens(context) AS context,
                 tam_fts_tokens(fix) AS fix, tam_fts_tokens(tags) AS tags FROM errors) AS tokens;

    DELETE FROM atomic_facts_tsv;
    INSERT INTO atomic_facts_tsv (id, content, doc_length)
    SELECT id, content, cardinality(content)
    FROM (SELECT id, tam_fts_tokens(content) AS content FROM atomic_facts) AS tokens;

    DELETE FROM evidence_passages_tsv;
    INSERT INTO evidence_passages_tsv (id, content, doc_length)
    SELECT id, content, cardinality(content)
    FROM (SELECT id, tam_fts_tokens(content) AS content FROM evidence_passages) AS tokens;

    DELETE FROM episodes_v11_tsv;
    INSERT INTO episodes_v11_tsv (id, summary, participants, outcome, doc_length)
    SELECT id, summary, participants, outcome, cardinality(summary) + cardinality(participants) + cardinality(outcome)
    FROM (SELECT id, tam_fts_tokens(summary) AS summary,
                 tam_fts_tokens(tam_fts_participants(participants)) AS participants,
                 tam_fts_tokens(COALESCE(outcome, '')) AS outcome FROM episodes_v11) AS tokens;

    UPDATE fts_stats SET doc_count = totals.documents, total_length = totals.tokens
    FROM (
        SELECT 'knowledge_tsv' AS source, count(*) AS documents, COALESCE(sum(doc_length), 0) AS tokens
        FROM knowledge_tsv
        UNION ALL SELECT 'errors_tsv', count(*), COALESCE(sum(doc_length), 0) FROM errors_tsv
        UNION ALL SELECT 'atomic_facts_tsv', count(*), COALESCE(sum(doc_length), 0) FROM atomic_facts_tsv
        UNION ALL SELECT 'evidence_passages_tsv', count(*), COALESCE(sum(doc_length), 0) FROM evidence_passages_tsv
        UNION ALL SELECT 'episodes_v11_tsv', count(*), COALESCE(sum(doc_length), 0) FROM episodes_v11_tsv
    ) AS totals
    WHERE fts_stats.source = totals.source;
END
$$;

-- ─── Graph names (migration 026) ───────────────────────────────────────────
-- SQLite rewrites name_norm in an AFTER trigger; a BEFORE trigger sets the same
-- value without a second write. lower() folds all of Unicode here, SQLite's only
-- ASCII; the Python callers (episodic.py) compare against str.lower().
CREATE FUNCTION tam_graph_nodes_name_norm() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.name_norm := lower(btrim(NEW.name, ' '));
    RETURN NEW;
END
$$;

CREATE TRIGGER graph_nodes_name_norm_ins BEFORE INSERT ON graph_nodes
    FOR EACH ROW EXECUTE FUNCTION tam_graph_nodes_name_norm();
CREATE TRIGGER graph_nodes_name_norm_upd BEFORE UPDATE OF name ON graph_nodes
    FOR EACH ROW EXECUTE FUNCTION tam_graph_nodes_name_norm();

-- ─── Graph link integrity (migration 031) ──────────────────────────────────
CREATE FUNCTION tam_knowledge_nodes_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM knowledge WHERE id = NEW.knowledge_id)
       OR NOT EXISTS (SELECT 1 FROM graph_nodes WHERE id = NEW.node_id) THEN
        RAISE EXCEPTION 'Graph link requires existing knowledge and node';
    END IF;
    RETURN NEW;
END
$$;

CREATE TRIGGER knowledge_nodes_insert_guard BEFORE INSERT ON knowledge_nodes
    FOR EACH ROW EXECUTE FUNCTION tam_knowledge_nodes_guard();
CREATE TRIGGER knowledge_nodes_update_guard BEFORE UPDATE OF knowledge_id, node_id ON knowledge_nodes
    FOR EACH ROW EXECUTE FUNCTION tam_knowledge_nodes_guard();

CREATE FUNCTION tam_knowledge_links_delete() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM knowledge_nodes WHERE knowledge_id = OLD.id;
    RETURN NULL;
END
$$;

CREATE TRIGGER knowledge_links_delete AFTER DELETE ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_knowledge_links_delete();

CREATE FUNCTION tam_node_links_delete() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM knowledge_nodes WHERE node_id = OLD.id;
    RETURN NULL;
END
$$;

CREATE TRIGGER node_links_delete AFTER DELETE ON graph_nodes
    FOR EACH ROW EXECUTE FUNCTION tam_node_links_delete();

CREATE FUNCTION tam_knowledge_links_id_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM knowledge_nodes WHERE knowledge_id = OLD.id) THEN
        RAISE EXCEPTION 'Cannot change linked knowledge identity';
    END IF;
    RETURN NEW;
END
$$;

CREATE TRIGGER knowledge_links_id_guard BEFORE UPDATE OF id ON knowledge
    FOR EACH ROW WHEN (OLD.id IS DISTINCT FROM NEW.id) EXECUTE FUNCTION tam_knowledge_links_id_guard();

CREATE FUNCTION tam_node_links_id_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM knowledge_nodes WHERE node_id = OLD.id) THEN
        RAISE EXCEPTION 'Cannot change linked node identity';
    END IF;
    RETURN NEW;
END
$$;

CREATE TRIGGER node_links_id_guard BEFORE UPDATE OF id ON graph_nodes
    FOR EACH ROW WHEN (OLD.id IS DISTINCT FROM NEW.id) EXECUTE FUNCTION tam_node_links_id_guard();

-- ─── Atomic facts follow their sources (migration 029 / Store._migrate) ────
CREATE FUNCTION tam_atomic_source_delete() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO atomic_fact_rebuild (knowledge_id)
        SELECT target_id FROM atomic_fact_dependencies WHERE source_id = OLD.id AND target_id <> OLD.id
        ON CONFLICT DO NOTHING;
    DELETE FROM atomic_fact_runs WHERE knowledge_id IN (
        SELECT target_id FROM atomic_fact_dependencies WHERE source_id = OLD.id
    ) OR knowledge_id = OLD.id;
    DELETE FROM atomic_facts WHERE knowledge_id IN (
        SELECT target_id FROM atomic_fact_dependencies WHERE source_id = OLD.id
    ) OR knowledge_id = OLD.id;
    DELETE FROM atomic_fact_dependencies WHERE target_id = OLD.id;
    DELETE FROM atomic_fact_rebuild WHERE knowledge_id = OLD.id;
    RETURN NULL;
END
$$;

CREATE TRIGGER atomic_source_delete AFTER DELETE ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_atomic_source_delete();

CREATE FUNCTION tam_atomic_source_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO atomic_fact_rebuild (knowledge_id)
        SELECT target_id FROM atomic_fact_dependencies WHERE source_id = OLD.id
        ON CONFLICT DO NOTHING;
    INSERT INTO atomic_fact_rebuild (knowledge_id)
        SELECT knowledge_id FROM atomic_fact_runs WHERE knowledge_id = OLD.id
        ON CONFLICT DO NOTHING;
    DELETE FROM atomic_fact_runs WHERE knowledge_id IN (
        SELECT target_id FROM atomic_fact_dependencies WHERE source_id = OLD.id
    ) OR knowledge_id = OLD.id;
    DELETE FROM atomic_facts WHERE knowledge_id IN (
        SELECT target_id FROM atomic_fact_dependencies WHERE source_id = OLD.id
    ) OR knowledge_id = OLD.id;
    RETURN NULL;
END
$$;

CREATE TRIGGER atomic_source_update
    AFTER UPDATE OF content, status, project, session_id, branch, created_at ON knowledge
    FOR EACH ROW WHEN (OLD.content IS DISTINCT FROM NEW.content OR OLD.status IS DISTINCT FROM NEW.status
                       OR OLD.project IS DISTINCT FROM NEW.project OR OLD.session_id IS DISTINCT FROM NEW.session_id
                       OR OLD.branch IS DISTINCT FROM NEW.branch OR OLD.created_at IS DISTINCT FROM NEW.created_at)
    EXECUTE FUNCTION tam_atomic_source_update();

-- ─── Evidence passages follow their sources (migrations 030, 033) ──────────
CREATE FUNCTION tam_evidence_source_invalidate() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM passage_sources WHERE knowledge_id = OLD.id;
    RETURN NULL;
END
$$;

CREATE TRIGGER evidence_source_update
    AFTER UPDATE OF content, status, project, branch, type, source_format ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_evidence_source_invalidate();
CREATE TRIGGER evidence_source_delete AFTER DELETE ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_evidence_source_invalidate();

CREATE FUNCTION tam_passage_source_delete() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    DELETE FROM evidence_passages WHERE knowledge_id = OLD.knowledge_id;
    RETURN NULL;
END
$$;

CREATE TRIGGER passage_source_delete AFTER DELETE ON passage_sources
    FOR EACH ROW EXECUTE FUNCTION tam_passage_source_delete();

-- ─── Vector index revision and change log (migrations 032, 036) ────────────
-- Every change to a searchable embedding bumps the revision once per row and logs
-- the affected record ids (an UPDATE logs the old and the new id), keeping the
-- newest 50,000 log rows, as the SQLite triggers do.
CREATE FUNCTION tam_vector_revision_bump() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    kept_changes CONSTANT bigint := 50000;
    current_revision bigint;
    old_record bigint;
    new_record bigint;
BEGIN
    IF TG_TABLE_NAME = 'embeddings' THEN
        IF TG_OP <> 'INSERT' THEN old_record := OLD.knowledge_id; END IF;
        IF TG_OP <> 'DELETE' THEN new_record := NEW.knowledge_id; END IF;
    ELSE
        IF TG_OP <> 'INSERT' THEN old_record := OLD.id; END IF;
        IF TG_OP <> 'DELETE' THEN new_record := NEW.id; END IF;
    END IF;
    UPDATE vector_index_revision SET revision = revision + 1 WHERE singleton = 1
        RETURNING revision INTO current_revision;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    IF old_record IS NOT NULL THEN
        INSERT INTO vector_changes (revision, knowledge_id) VALUES (current_revision, old_record);
    END IF;
    IF new_record IS NOT NULL THEN
        INSERT INTO vector_changes (revision, knowledge_id) VALUES (current_revision, new_record);
    END IF;
    DELETE FROM vector_changes WHERE seq <= (SELECT max(seq) FROM vector_changes) - kept_changes;
    RETURN NULL;
END
$$;

CREATE TRIGGER vector_revision_embedding_insert AFTER INSERT ON embeddings
    FOR EACH ROW EXECUTE FUNCTION tam_vector_revision_bump();
CREATE TRIGGER vector_revision_embedding_update AFTER UPDATE ON embeddings
    FOR EACH ROW EXECUTE FUNCTION tam_vector_revision_bump();
CREATE TRIGGER vector_revision_embedding_delete AFTER DELETE ON embeddings
    FOR EACH ROW EXECUTE FUNCTION tam_vector_revision_bump();
CREATE TRIGGER vector_revision_knowledge_insert AFTER INSERT ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_vector_revision_bump();
CREATE TRIGGER vector_revision_knowledge_update AFTER UPDATE OF id, status, project, type, branch ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_vector_revision_bump();
CREATE TRIGGER vector_revision_knowledge_delete AFTER DELETE ON knowledge
    FOR EACH ROW EXECUTE FUNCTION tam_vector_revision_bump();

-- ─── SQLite -> PostgreSQL migration quarantine (PostgreSQL only) ───────────
-- Rows the migration copier could not place (orphans) are kept here verbatim
-- instead of blocking the migration; purging the workspace drops them with it.
CREATE TABLE migration_quarantine (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_table text NOT NULL,
    source_pk text NOT NULL,
    row jsonb NOT NULL,
    reason text NOT NULL,
    migrated_at text NOT NULL
);
CREATE INDEX idx_migration_quarantine_source ON migration_quarantine (source_table);

